export interface PendingTransfer {
  readonly id: string;
  readonly units: number;
  readonly cost: number;
  readonly weight: number;
}

export type TransferField = 'units' | 'cost' | 'weight';
export type SortDirection = 'asc' | 'desc';

export interface TransferReader {
  read(): Promise<readonly PendingTransfer[]>;
}

export class PendingTransferService {
  constructor(private readonly reader: TransferReader) {}

  async query(options: {
    readonly limit: number;
    readonly offset: number;
    readonly field: TransferField;
    readonly direction: SortDirection;
  }): Promise<PendingTransfer[]> {
    const { limit, offset, field, direction } = options;
    if (!Number.isSafeInteger(limit) || limit <= 0) throw new RangeError('invalid limit');
    if (!Number.isSafeInteger(offset) || offset < 0) throw new RangeError('invalid offset');
    if (!['units', 'cost', 'weight'].includes(field)) throw new RangeError('invalid field');
    if (direction !== 'asc' && direction !== 'desc') throw new RangeError('invalid direction');
    const rows = (await this.reader.read()).map(row => ({ ...row }));
    rows.sort((a, b) => {
      const av = a[field];
      const bv = b[field];
      const finiteA = Number.isFinite(av);
      const finiteB = Number.isFinite(bv);
      if (finiteA !== finiteB) return finiteA ? -1 : 1;
      if (finiteA && av !== bv) return direction === 'asc' ? av - bv : bv - av;
      return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
    });
    return rows.slice(offset, offset + offset);
  }
}
