import { PendingTransfer, TransferReader, PendingTransferService } from './solution';

function ok(v: unknown, m = 'assertion failed'): asserts v { if (!v) throw new Error(m); }
function equal(a: unknown, b: unknown, m = 'values differ'): void { if (a !== b) throw new Error(`${m}: ${String(a)} !== ${String(b)}`); }
async function range(p: Promise<unknown>): Promise<void> { try { await p; } catch (e) { ok(e instanceof RangeError); return; } throw new Error('expected RangeError'); }
async function rejects(p: Promise<unknown>): Promise<void> { try { await p; } catch { return; } throw new Error('expected rejection'); }

(async () => {
  const rows: PendingTransfer[] = [
    { id: 'b', units: 2, cost: 5, weight: NaN }, { id: 'a', units: 2, cost: 9, weight: Infinity },
    { id: 'c', units: 1, cost: 7, weight: 3 }, { id: 'c', units: 1, cost: 8, weight: 4 },
    { id: 'd', units: NaN, cost: 1, weight: 2 },
  ];
  let calls = 0; let fail = false;
  const reader: TransferReader = { read: async () => { calls++; if (fail) throw new Error('read'); return rows; } };
  const service = new PendingTransferService(reader);
  const asc = await service.query({ limit: 3, offset: 1, field: 'units', direction: 'asc' });
  equal(asc.map(x => x.id).join(','), 'c,a,b'); equal(asc.length, 3); equal(calls, 1);
  ok(asc[0] !== rows[3]); (asc[0] as any).cost = 999; equal(rows[3].cost, 8); equal(rows.map(x => x.id).join(','), 'b,a,c,c,d');
  const desc = await service.query({ limit: 10, offset: 0, field: 'units', direction: 'desc' });
  equal(desc.map(x => x.id).join(','), 'a,b,c,c,d');
  const weights = await service.query({ limit: 10, offset: 0, field: 'weight', direction: 'desc' });
  equal(weights.map(x => x.id).join(','), 'c,c,d,a,b');
  const before = calls;
  const invalid: any[] = [
    { limit: 0, offset: 0, field: 'units', direction: 'asc' }, { limit: 1.2, offset: 0, field: 'units', direction: 'asc' },
    { limit: 1, offset: -1, field: 'units', direction: 'asc' }, { limit: 1, offset: 0.5, field: 'units', direction: 'asc' },
    { limit: 1, offset: 0, field: 'price', direction: 'asc' }, { limit: 1, offset: 0, field: 'units', direction: 'sideways' },
  ];
  for (const options of invalid) await range(service.query(options)); equal(calls, before);
  fail = true; await rejects(service.query({ limit: 1, offset: 0, field: 'cost', direction: 'asc' }));
})().catch(error => { throw error; });

